function nextFree(used, k) {
  const n = used.length
  let i = 0
  while (i < n) {
    const v = used[i]
    if (v >= 1 && v <= n && used[v - 1] !== v) [used[i], used[v - 1]] = [used[v - 1], v]
    else i++
  }
  const free = []
  const big = new Set()
  for (let j = 0; j < n; j++) {
    if (used[j] !== j + 1) {
      if (free.length < k) free.push(j + 1)
      if (used[j] > n) big.add(used[j])
    }
  }
  for (let x = n + 1; free.length < k; x++) if (!big.has(x)) free.push(x)
  return free
}

