def next_free(used, k):
    n = len(used)
    i = 0
    while i < n:
        v = used[i]
        if 1 <= v <= n and used[v - 1] != v:
            used[i], used[v - 1] = used[v - 1], v
        else:
            i += 1
    free = []
    big = set()
    for j in range(n):
        if used[j] != j + 1:
            if len(free) < k:
                free.append(j + 1)
            if used[j] > n:
                big.add(used[j])
    x = n + 1
    while len(free) < k:
        if x not in big:
            free.append(x)
        x += 1
    return free
